INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist beim BDSG entscheidend?', 2, '[{"text": "Ergänzung der DSGVO", "correct": true, "because": "Konkretisiert nationale Regeln"}, {"text": "Farbe der Gesetzestexte", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG unabhängig von der DSGVO anwendbar?', 1, '[{"text": "Nein", "correct": true, "because": "Es ergänzt die DSGVO"}, {"text": "Ja", "correct": false, "because": "DSGVO hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche regelt das BDSG zusätzlich zur DSGVO?', 5, '[{"text": "Beschäftigtendatenschutz", "correct": true, "because": "Nationale Spezifika"}, {"text": "Videoüberwachung", "correct": true, "because": "Detailregelungen"}, {"text": "Schriftgröße der Dokumente", "correct": false, "because": "Kein Einfluss"}, {"text": "Datenschutzbeauftragte", "correct": true, "because": "Konkretisierte Pflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über das BDSG richtig? a) Es gilt nur für öffentliche Stellen. b) Es konkretisiert DSGVO-Öffnungsklauseln.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Gilt auch für Unternehmen"}, {"text": "Nur b) stimmt", "correct": true, "because": "Konkretisierung ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Umsetzung des BDSG ignorieren?', 2, '[{"text": "Datenschutzbeauftragtenpflicht", "correct": false, "because": "Wichtig nach §38"}, {"text": "Farbe der Datenschutzberichte", "correct": true, "because": "Kein Einfluss"}, {"text": "Videoüberwachungsvorschriften", "correct": false, "because": "Relevante Regelung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist beim BDSG entscheidend für die Datenverarbeitung?', 2, '[{"text": "Rechtsgrundlage", "correct": true, "because": "Legitimiert Verarbeitung"}, {"text": "Farbe der Berichte", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG eine eigenständige Regelung unabhängig von der DSGVO?', 1, '[{"text": "Nein", "correct": true, "because": "Ergänzt DSGVO in Deutschland"}, {"text": "Ja", "correct": false, "because": "Abhängig von DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind im BDSG wichtig?', 5, '[{"text": "Datenverarbeitung durch Behörden", "correct": true, "because": "Spezifische Regelung"}, {"text": "Schutz personenbezogener Daten", "correct": true, "because": "Kern des Gesetzes"}, {"text": "Design der Webseite", "correct": false, "because": "Kein Einfluss"}, {"text": "Videoüberwachung", "correct": true, "because": "Reguliert durch BDSG"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über das BDSG richtig? a) Es ergänzt die DSGVO. b) Es gilt nur für private Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt auch für Behörden"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur privat"}, {"text": "Nur b) stimmt", "correct": false, "because": "Ergänzung DSGVO"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du beim BDSG ignorieren?', 2, '[{"text": "Rechtsgrundlage für Datenverarbeitung", "correct": false, "because": "Wichtig für Konformität"}, {"text": "Farbe der Datenschutzerklärung", "correct": true, "because": "Kein Einfluss"}, {"text": "Zweckbindung", "correct": false, "because": "Kernprinzip"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist beim BDSG entscheidend für die Datenverarbeitung?', 2, '[{"text": "Zweckbindung", "correct": true, "because": "Daten nur für festgelegte Zwecke"}, {"text": "Farbe der Datenschutzerklärung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG nur für öffentliche Stellen relevant?', 1, '[{"text": "Nein", "correct": true, "because": "Gilt auch für private Unternehmen"}, {"text": "Ja", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt das BDSG an die Datenverarbeitung?', 5, '[{"text": "Datensparsamkeit", "correct": true, "because": "Nur nötige Daten erheben"}, {"text": "Transparenz", "correct": true, "because": "Betroffene informieren"}, {"text": "Schriftgröße der Dokumente", "correct": false, "because": "Kein Einfluss"}, {"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schutz der Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über das BDSG richtig? a) Es ergänzt die DSGVO in Deutschland. b) Es gilt nur für personenbezogene Daten von Mitarbeitern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle personenbezogenen Daten"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht nur Mitarbeiter"}, {"text": "Nur b) stimmt", "correct": false, "because": "Ergänzt DSGVO"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du beim BDSG ignorieren?', 2, '[{"text": "Datenschutzbeauftragter", "correct": false, "because": "Pflicht bei bestimmten Firmen"}, {"text": "Farbe der Datenschutzrichtlinie", "correct": true, "because": "Kein Einfluss"}, {"text": "Datenverarbeitungsverzeichnis", "correct": false, "because": "Gesetzlich vorgeschrieben"}]');
